// Native share: the fixed 380×520 scene, Pure Black palette, field seeds and
// star density match the ImGui renderer. The preview time is independent.
const SPACE_DESIGN_PRODUCTS = [[0,'PUBG'],[1,'TalesRunner'],[2,'Lost Saga'],[3,'Apex Legends'],
  [4,'Overwatch'],[5,'Counter-Strike 2'],[12,'Roblox']];
const SPACE_DESIGN_LOAD_STAGES = ['Checking license','Verifying session','Preparing transfer',
  'Downloading workspace','Verifying download','Preparing workspace'];
const SPACE_DESIGN_THRESHOLDS = [.12,.40,.60,.89,.93,1];
const SPACE_DESIGN_PHASES = [['earth','지구'],['loading','로딩'],['complete','완료']];
let spaceDesignEarthOutline;

function spaceDesignSeed(value) {
  value = Math.imul(value ^ value >>> 16, 0x7feb352d);
  value = Math.imul(value ^ value >>> 15, 0x846ca68b);
  return ((value ^ value >>> 16) & 65535) / 65535;
}

const SPACE_DESIGN_STARS = Array.from({length:16 * 22}, (_, index) => {
  const seed = 1103 + index * 9;
  return {
    x:index % 16 + .15 + .7 * spaceDesignSeed(seed + 2),
    y:Math.floor(index / 16) + .15 + .7 * spaceDesignSeed(seed + 3),
    phase:2 * Math.PI * spaceDesignSeed(seed), rate:.34 + .65 * spaceDesignSeed(seed + 1),
    light:.14 + .31 * spaceDesignSeed(seed + 4), radius:.36 + .45 * spaceDesignSeed(seed + 5),
    visibleAt:spaceDesignSeed(seed + 6), cross:index % 29 === 7
  };
});

function spaceDesignCircle(ctx, x, y, radius) {
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, 2 * Math.PI);
}

function spaceDesignStarField(ctx, density, elapsed) {
  if (density <= 0) return;
  for (const star of SPACE_DESIGN_STARS) {
    if (density < 100 && star.visibleAt >= density / 100) continue;
    const t = elapsed * star.rate;
    const twinkle = .70 + .30 * Math.sin(2.1 * t + star.phase);
    const x = 34 + 19.5 * (star.x + .075 * Math.cos(t + star.phase));
    const y = 34 + 452 / 22 * (star.y + .065 * Math.sin(t + star.phase));
    ctx.fillStyle = `rgba(173,194,224,${star.light * twinkle})`;
    spaceDesignCircle(ctx, x, y, star.radius);
    ctx.fill();
    if (star.cross) {
      const ray = 2 + .6 * twinkle;
      ctx.strokeStyle = `rgba(173,194,224,${.37 + .24 * twinkle})`;
      ctx.lineWidth = .8;
      ctx.beginPath();
      ctx.moveTo(x - ray, y);
      ctx.lineTo(x + ray, y);
      ctx.moveTo(x, y - ray);
      ctx.lineTo(x, y + ray);
      ctx.stroke();
    }
  }
}

function spaceDesignEarth(ctx, x, y, scale, softened, elapsed) {
  if (!spaceDesignEarthOutline) spaceDesignEarthOutline = new Path2D(SPACE_DESIGN_EARTH_PATH);
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  if (softened) {
    ctx.fillStyle = 'rgba(118,120,127,.045)';
    spaceDesignCircle(ctx, 0, 0, 103);
    ctx.fill();
    ctx.strokeStyle = 'rgba(118,120,127,.10)';
    ctx.lineWidth = 3.3;
    ctx.stroke(spaceDesignEarthOutline);
  }
  ctx.strokeStyle = softened ? 'rgba(118,120,127,.22)' : '#303239';
  ctx.lineWidth = 1.25;
  ctx.stroke(spaceDesignEarthOutline);
  spaceDesignCircle(ctx, 0, 0, 103);
  ctx.stroke();
  if (!softened) {
    for (const [index, offset] of [-.56,1.68,3.63].entries()) {
      const angle = offset + elapsed * 2 * Math.PI / [12,16.1,20.4][index];
      const radius = 103 * [1.22,1.32,1.42][index];
      ctx.save();
      ctx.translate(radius * Math.cos(angle), radius * Math.sin(angle));
      ctx.rotate(angle + Math.PI / 2);
      ctx.strokeRect(-3, -2.8, 6, 5.6);
      ctx.strokeRect(-12.5, -2.1, 7.8, 4.2);
      ctx.strokeRect(4.7, -2.1, 7.8, 4.2);
      ctx.restore();
    }
  }
  ctx.restore();
}

function spaceDesignLoader(ctx, x, y, radius, phase, fill, elapsed, reveal) {
  if (phase === 'loading') {
    const sweep = (.38 + .35 * fill) * 2 * Math.PI;
    const start = elapsed * 3.65;
    const segments = 62;
    ctx.lineWidth = radius * .22;
    for (let i = 0; i < segments; i++) {
      const t = (i + 1) / segments;
      ctx.strokeStyle = `rgba(${Math.round(194 + 61 * t)},${Math.round(72 + 90 * t)},${Math.round(32 + 59 * t)},${.08 + .90 * t * t})`;
      ctx.beginPath();
      ctx.arc(x, y, radius * .89, start + (i / segments) * sweep, start + t * sweep + .008);
      ctx.stroke();
    }
  } else {
    const ease = reveal * reveal * (3 - 2 * reveal);
    const markRadius = radius * (.88 + .12 * ease);
    ctx.lineWidth = 2.7;
    ctx.strokeStyle = `rgba(128,224,181,${.44 * reveal})`;
    spaceDesignCircle(ctx, x, y, markRadius);
    ctx.stroke();
    ctx.strokeStyle = `rgba(128,224,181,${reveal})`;
    ctx.beginPath();
    ctx.moveTo(x - markRadius * .42, y - markRadius * .03);
    const first = Math.min(1, 2 * ease);
    ctx.lineTo(x + markRadius * (-.42 + .29 * first), y + markRadius * (-.03 + .30 * first));
    if (ease > .5) {
      const second = 2 * ease - 1;
      ctx.lineTo(x + markRadius * (-.13 + .60 * second), y + markRadius * (.27 - .60 * second));
    }
    ctx.stroke();
  }
}

function spaceDesignOverlay(ctx, profile, product) {
  for (const [index, label] of ['General','Market','Usage','Settings'].entries()) {
    const y = 44 + index * 42;
    if (index === 0) {
      ctx.fillStyle = '#27282b';
      ctx.beginPath();
      ctx.roundRect(25, y - 15, 69, 30, 7);
      ctx.fill();
    }
    ctx.font = '16px Consolas, monospace';
    ctx.fillStyle = index === 0 ? '#f2f5fb' : '#a8aab1';
    ctx.fillText(label, 59.5, y, 63);
  }
  const baseX = 217 + 15 * (product % 3);
  const baseY = 192 + 11 * (Math.floor(product / 3) % 3);
  const x = baseX + profile.x, y = baseY + profile.y;
  const seed = 0x7431 + (product + 1) * 1193;
  const spread = (45 + 5 * (product % 4)) * profile.scale / 100;
  const count = 5 + product % 4;
  const angle = 2 * Math.PI * spaceDesignSeed(seed + 19);
  const points = Array.from({length:count}, (_, index) => {
    const seedIndex = seed + index * 13;
    const bearing = angle + 2 * Math.PI / count * index + (spaceDesignSeed(seedIndex) - .5) * .55;
    const radius = spread * (.36 + .63 * spaceDesignSeed(seedIndex + 1));
    return [x + Math.cos(bearing) * radius,y + Math.sin(bearing) * radius];
  });
  ctx.save();
  ctx.beginPath();
  ctx.rect(98,109,253,236);
  ctx.clip();
  ctx.lineWidth = 1;
  ctx.strokeStyle = '#45484f';
  for (const [start,end] of [[0,1.15],[2.62,3.32]]) {
    ctx.beginPath();
    ctx.arc(x, y, spread + 9, angle + start, angle + end);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.moveTo(...points[0]);
  for (const point of points.slice(1)) ctx.lineTo(...point);
  ctx.moveTo(...points[0]);
  ctx.lineTo(...points[Math.floor((count + 1) / 2)]);
  ctx.stroke();
  ctx.fillStyle = '#808489';
  for (const [index,[pointX,pointY]] of points.entries()) {
    spaceDesignCircle(ctx, pointX, pointY, index === product % count ? 2.65 : 1.5);
    ctx.fill();
  }
  ctx.fillStyle = '#f2f5fb';
  ctx.font = `${22.75 * profile.labelScale / 100}px Consolas, monospace`;
  ctx.fillText(SPACE_DESIGN_PRODUCTS.find(([id]) => id === product)[1],
    baseX + profile.labelX, baseY + 80 + profile.labelY, 192);
  ctx.restore();
}

function drawSpaceDesign(canvas, stage, profile, phase, product, elapsed = 0, fill = .65, reveal = 1) {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const width = 380, height = 520;
  const dpi = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
  const pixelWidth = Math.round(width * dpi), pixelHeight = Math.round(height * dpi);
  if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
    canvas.width = pixelWidth;
    canvas.height = pixelHeight;
  }
  ctx.setTransform(pixelWidth / width, 0, 0, pixelHeight / height, 0, 0);
  ctx.clearRect(0, 0, width, height);
  ctx.beginPath();
  ctx.roundRect(20,20,340,480,12);
  ctx.fillStyle = '#000';
  ctx.fill();
  ctx.strokeStyle = '#0e0f13';
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  spaceDesignStarField(ctx, profile.stars, elapsed);
  if (stage === 'o') {
    spaceDesignOverlay(ctx, profile, product);
    return;
  }
  const x = 190 + profile.x;
  const y = 250 + profile.y;
  const scale = profile.scale / 100;
  spaceDesignEarth(ctx, x, y, scale, phase !== 'earth', elapsed);
  if (phase === 'earth') return;
  spaceDesignLoader(ctx, x, y, 43 * scale, phase, fill, elapsed, reveal);
  const label = phase === 'complete' ? 'Complete' : SPACE_DESIGN_LOAD_STAGES[SPACE_DESIGN_THRESHOLDS.findIndex(mark => fill < mark)];
  ctx.fillStyle = `rgba(242,245,251,${reveal})`;
  ctx.font = `${16.5 * profile.labelScale / 100}px Consolas, monospace`;
  ctx.fillText(label, 190 + profile.labelX, 322 + profile.labelY);
}

async function renderDesktopUiDesign(silent) {
  if (silent && content.querySelector('[data-space-design-editor]')) return;
  const owner = session.csrf;
  const result = await api(SPACE_DESIGN_API);
  guardAdminViewCommit('simulator');
  adminViewContent.html = `
    <section class="space-design-editor" data-space-design-editor>
      <div class="space-design-preview">
        <div class="space-design-preview-header">
          <div>
            <h2>미리보기</h2>
            <p>모티프, 텍스트와 별 배치를 조정합니다.</p>
          </div>
          <div class="space-design-stage-picker" role="group" aria-label="미리보기 단계">
            <button type="button" data-design-stage="b" aria-pressed="true">B</button>
            <button type="button" data-design-stage="o" aria-pressed="false">O</button>
          </div>
        </div>
        <div class="space-design-preview-options">
          <div class="space-design-phase-picker" data-design-b-options role="group" aria-label="B 화면 단계">
            ${SPACE_DESIGN_PHASES.map(([value, label]) => `<button class="btn" type="button" data-design-phase="${value}" aria-pressed="${value === 'earth'}">${label}</button>`).join('')}
            <button class="btn" type="button" data-design-play>재생</button>
          </div>
          <label class="space-design-product-picker" data-design-o-options hidden>
            <span>미리보기 게임</span>
            <select>${SPACE_DESIGN_PRODUCTS.map(([value, title]) => `<option value="${value}">${title}</option>`).join('')}</select>
          </label>
        </div>
        <div class="space-design-window">
          <canvas width="380" height="520" role="img" aria-label="B 라이선스 화면 배치"></canvas>
        </div>
      </div>
      <div class="space-design-properties">
        <div class="space-design-controls-header"><h2>화면 설정</h2><span data-design-revision></span></div>
        <fieldset class="space-design-controls">
          <legend class="space-design-sr-label">선택한 화면의 배치 속성</legend>
          ${SPACE_DESIGN_CONTROLS.map(([name, label, min, max]) => `
            <label class="space-design-control">
              <span>${label}</span>
              <output data-design-value="${name}"></output>
              <input type="range" data-design-field="${name}" min="${min}" max="${max}" step="1">
            </label>`).join('')}
        </fieldset>
        <p class="space-design-publish-note">게시한 설정은 다음 인증 실행에서 B와 O에 적용됩니다.</p>
        <div class="space-design-actions">
          <button class="btn" type="button" data-design-reset>기본값</button>
          <button class="btn" type="button" data-design-reload>게시본 가져오기</button>
          <button class="btn primary" type="button" data-design-publish>게시</button>
        </div>
        <p class="space-design-status" role="status" aria-live="polite"></p>
      </div>
    </section>`;
  const editor = content.querySelector('[data-space-design-editor]');
  const canvas = editor.querySelector('canvas');
  const status = editor.querySelector('[role="status"]');
  const controls = editor.querySelector('fieldset');
  const publish = editor.querySelector('[data-design-publish]');
  const reload = editor.querySelector('[data-design-reload]');
  const reset = editor.querySelector('[data-design-reset]');
  const stageButtons = [...editor.querySelectorAll('[data-design-stage]')];
  const inputs = [...editor.querySelectorAll('[data-design-field]')];
  const bOptions = editor.querySelector('[data-design-b-options]');
  const oOptions = editor.querySelector('[data-design-o-options]');
  const phaseButtons = [...editor.querySelectorAll('[data-design-phase]')];
  const play = editor.querySelector('[data-design-play]');
  const product = oOptions.querySelector('select');
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let phase = 'earth';
  let stageProduct = Number(product.value);
  let animation = 0;
  let previewElapsed = 0;
  let previewFill = .65;
  let previewReveal = 1;
  let activeStage = 'b';
  let published = result.design;
  let draft = structuredClone(published);
  let busy = false;

  function isCurrent() {
    return editor.isConnected && currentView === 'simulator' && session?.csrf === owner;
  }

  function paint() {
    const profile = draft[activeStage];
    stageButtons.forEach(button => button.setAttribute('aria-pressed', String(button.dataset.designStage === activeStage)));
    bOptions.hidden = activeStage !== 'b';
    oOptions.hidden = activeStage !== 'o';
    play.disabled = reducedMotion.matches;
    phaseButtons.forEach(button => button.setAttribute('aria-pressed', String(button.dataset.designPhase === phase)));
    for (const [name, , , , unit] of SPACE_DESIGN_CONTROLS) {
      editor.querySelector(`[data-design-field="${name}"]`).value = profile[name];
      editor.querySelector(`[data-design-value="${name}"]`).value = `${profile[name]}${unit}`;
    }
    editor.querySelector('[data-design-revision]').textContent = `게시 버전 ${published.revision}`;
    const phaseName = SPACE_DESIGN_PHASES.find(([value]) => value === phase)[1];
    canvas.setAttribute('aria-label', activeStage === 'b' ? `B 라이선스 화면 · ${phaseName}` : 'O 일반 탭 화면 배치');
    drawSpaceDesign(canvas, activeStage, profile, phase, stageProduct, previewElapsed, previewFill, previewReveal);
    publish.disabled = busy || JSON.stringify(draft) === JSON.stringify(published);
  }

  function setBusy(value) {
    busy = value;
    controls.disabled = busy;
    reset.disabled = busy;
    reload.disabled = busy;
    paint();
  }

  function stopPreview() {
    window.cancelAnimationFrame(animation);
    animation = 0;
    play.textContent = '재생';
  }

  stageButtons.forEach(button => button.addEventListener('click', () => {
    stopPreview();
    activeStage = button.dataset.designStage;
    paint();
  }));
  phaseButtons.forEach(button => button.addEventListener('click', () => {
    stopPreview();
    phase = button.dataset.designPhase;
    previewElapsed = 0;
    previewFill = .65;
    previewReveal = 1;
    paint();
  }));
  product.addEventListener('change', () => {
    stageProduct = Number(product.value);
    paint();
  });
  play.addEventListener('click', () => {
    if (animation) {
      stopPreview();
      return;
    }
    if (reducedMotion.matches) return;
    const start = performance.now();
    play.textContent = '정지';
    function frame(now) {
      if (!isCurrent() || reducedMotion.matches) {
        stopPreview();
        return;
      }
      previewElapsed = Math.max(0, (now - start) / 1000);
      if (previewElapsed < .8) {
        phase = 'earth';
      } else if (previewElapsed < 5.8) {
        phase = 'loading';
        previewFill = Math.min(.99, (previewElapsed - .8) / 5);
        previewReveal = 1;
      } else {
        phase = 'complete';
        previewReveal = Math.min(1, (previewElapsed - 5.8) / .4);
        if (previewReveal === 1) {
          stopPreview();
          paint();
          return;
        }
      }
      paint();
      animation = window.requestAnimationFrame(frame);
    }
    animation = window.requestAnimationFrame(frame);
  });
  inputs.forEach(input => input.addEventListener('input', () => {
    const field = input.dataset.designField;
    if (activeStage === 'b' && phase === 'earth' && field.startsWith('label')) {
      stopPreview();
      phase = 'loading';
    }
    draft[activeStage][field] = input.valueAsNumber;
    paint();
  }));
  reset.addEventListener('click', () => {
    const profile = draft[activeStage];
    Object.assign(profile, SPACE_DESIGN_DEFAULT);
    paint();
  });
  reload.addEventListener('click', async () => {
    if (busy) return;
    setBusy(true);
    status.textContent = '최신 게시본을 확인 중입니다.';
    try {
      const response = await api(SPACE_DESIGN_API);
      if (!isCurrent()) return;
      published = response.design;
      draft = structuredClone(published);
      status.textContent = '게시된 설정을 불러왔습니다.';
    } catch (error) {
      if (isCurrent()) status.textContent = '게시본을 불러오지 못했습니다.';
    } finally {
      if (isCurrent()) setBusy(false);
    }
  });
  publish.addEventListener('click', async () => {
    if (busy) return;
    setBusy(true);
    status.textContent = '화면 설정을 게시 중입니다.';
    try {
      const response = await api(SPACE_DESIGN_API, {method:'POST',body:draft});
      if (!isCurrent()) return;
      published = response.design;
      draft = structuredClone(published);
      status.textContent = '게시했습니다. 다음 B 또는 O 실행에 적용됩니다.';
    } catch (error) {
      if (isCurrent()) {
        status.textContent = String(error.message).includes('DESKTOP_DESIGN_CONFLICT')
          ? '다른 게시본이 저장되었습니다. 최신 게시본을 불러와 다시 수정해 주세요.'
          : '화면 설정을 게시하지 못했습니다.';
      }
    } finally {
      if (isCurrent()) setBusy(false);
    }
  });
  paint();
}
